// Общие шаги для просмотрщика сторис (#f71f8d): лента story_feed, вход из ряда, тапы по краям, прогресс-бар.
// Селекторы сверены на живом сайте 04.11 (WebKit, iPhone 13 Mini): кружки ряда — кнопки с аватаром автора,
// шапка — кнопка с именем автора, «פעולות על הסטורי», «סגירה»; поле «תגובה ל<имя>…»; «אהבתי».
// RTL: тап по ЛЕВОМУ краю медиа — следующая сторис, по ПРАВОМУ — предыдущая.
import { expect, devices, type Browser, type Locator, type Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { saveSession } from '../_shared/session';

export type FeedStory = {
  id: string;
  author_id: string;
  image_url: string;
  caption: string | null;
  created_at: string;
  author_name: string;
  author_avatar_url: string | null;
};
export type Group = { authorId: string; name: string; avatar: string | null; stories: FeedStory[] };

const isFeed = (url: string) => url.includes('/rest/v1/story_feed');

// «Просмотрено» хранится на устройстве (localStorage «stories.seen») и попадает в сохранённую сессию —
// просмотрщик пропускает просмотренные сторис. Каждый тест начинает с чистой отметкой (один раз на вкладку).
export const SEEN_KEY = 'stories.seen';
export async function resetSeen(page: Page) {
  await page.addInitScript((key) => {
    if (sessionStorage.getItem('qa-seen-reset')) return;
    sessionStorage.setItem('qa-seen-reset', '1');
    localStorage.removeItem(key);
  }, SEEN_KEY);
}

// Открыть /discover и вернуть ответ story_feed (источник ожидаемых данных: какие сторис и у кого).
export async function openDiscover(page: Page): Promise<FeedStory[]> {
  await resetSeen(page);
  const feed = page.waitForResponse((r) => isFeed(r.url()) && r.request().method() === 'GET');
  await page.goto('/discover');
  const res = await feed;
  expect(res.ok(), 'story_feed отвечает').toBeTruthy();
  return (await res.json()) as FeedStory[];
}

// Группы по авторам в порядке первой сторис (так идёт ряд и переход между авторами).
export function groupsOf(feed: FeedStory[]): Group[] {
  const map = new Map<string, Group>();
  for (const s of feed) {
    if (!map.has(s.author_id)) map.set(s.author_id, { authorId: s.author_id, name: s.author_name, avatar: s.author_avatar_url, stories: [] });
    map.get(s.author_id)!.stories.push(s);
  }
  return [...map.values()];
}

// Группы в порядке кружков ряда сторис (просмотрщик идёт по ряду: от выбранного автора к следующим).
// Порядок ряда берём со страницы: на 04.11 это «свежая сторис — раньше», но тест не зависит от правила сортировки.
export async function groupsInRow(page: Page, feed: FeedStory[]): Promise<Group[]> {
  const groups = groupsOf(feed);
  for (const g of groups) await expect(storyCircle(page, g.authorId)).toBeVisible();
  const order: string[] = await page.locator('button img[src*="/avatars/"]').evaluateAll((imgs) =>
    imgs.map((i) => (i as HTMLImageElement).src.split('/avatars/')[1]?.split('/')[0] ?? ''),
  );
  const pos = (id: string) => order.indexOf(id);
  return groups.sort((a, b) => pos(a.authorId) - pos(b.authorId));
}

export function requireGroups(feed: FeedStory[] | Group[], min = 1): Group[] {
  const g = feed.length && 'stories' in (feed[0] as object) ? (feed as Group[]) : groupsOf(feed as FeedStory[]);
  if (g.length < min) throw new Error(`Предусловие: в ленте сторис зрителя нужно ≥${min} автор(ов), сейчас ${g.length}. Нужны активные сторис QA-AUTO (24 ч) у авторов той же аудитории — см. .qa/tests/stories-viewer/`);
  return g;
}

// Тап по координатам, когда элемент — верхний в своей точке (ушёл сплэш/прелоадер, закончилась анимация).
export async function tapWhenTopmost(page: Page, target: Locator) {
  await expect(target).toBeVisible();
  await expect
    .poll(() =>
      target.evaluate((el) => {
        const r = el.getBoundingClientRect();
        const top = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
        return !!top && el.contains(top);
      }),
    )
    .toBe(true);
  const box = (await target.boundingBox())!;
  await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2);
}

// Кружок автора в ряду сторис (кнопка с его аватаром).
export const storyCircle = (page: Page, authorId: string) =>
  page.getByRole('button').filter({ has: page.locator(`img[src*="/avatars/${authorId}/"]`) }).first();

export async function openAuthor(page: Page, g: Group) {
  await tapWhenTopmost(page, storyCircle(page, g.authorId));
  await page.waitForURL(/\/story\//);
}

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Кнопка автора в шапке просмотрщика (имя + «מאומת/ת» у верифицированных).
export const authorButton = (page: Page, name: string) => page.getByRole('button', { name: new RegExp('^' + esc(name)) });
export const closeButton = (page: Page) => page.getByRole('button', { name: 'סגירה' });
export const menuButton = (page: Page) => page.getByRole('button', { name: 'פעולות על הסטורי' });
export const replyBox = (page: Page) => page.getByRole('textbox', { name: /^תגובה ל/ });
export const likeButton = (page: Page) => page.getByRole('button', { name: 'אהבתי' });
export const storyImage = (page: Page, s: FeedStory) => page.locator(`img[src="${s.image_url}"]`).first();

// Сегменты прогресса: у них нет роли, поэтому — по структуре: строка сегментов стоит прямо над шапкой с кнопкой автора.
export const segments = (page: Page, name: string) => authorButton(page, name).locator('xpath=../preceding-sibling::div[1]/div');

// Доля заполнения каждого сегмента (0…1): ширина белого заполнения / ширина дорожки.
export async function fills(page: Page, name: string): Promise<number[]> {
  return segments(page, name).evaluateAll((tracks) =>
    tracks.map((t) => {
      const fill = t.firstElementChild as HTMLElement | null;
      const w = t.getBoundingClientRect().width;
      return fill && w ? Math.round((fill.getBoundingClientRect().width / w) * 100) / 100 : 0;
    }),
  );
}

// Дождаться, что показана сторис s автора g: её картинка видна и прогресс текущего сегмента пошёл (картинка загрузилась).
export async function expectShowing(page: Page, g: Group, index: number) {
  await expect(authorButton(page, g.name)).toBeVisible();
  await expect(storyImage(page, g.stories[index])).toBeVisible();
  await expect(segments(page, g.name)).toHaveCount(g.stories.length);
  await expect.poll(async () => (await fills(page, g.name))[index] ?? 0).toBeGreaterThan(0);
}

// Тап по краю медиа (середина по высоте). Левый край — следующая, правый — предыдущая (RTL).
export async function tapSide(page: Page, side: 'left' | 'right') {
  const vp = page.viewportSize()!;
  await page.mouse.click(side === 'left' ? Math.round(vp.width * 0.12) : Math.round(vp.width * 0.88), Math.round(vp.height * 0.5));
}

// Окно роли на iPhone 13 Mini (WebKit) — для файлов @data, которые идут в проекте data.
export async function iphoneAs(browser: Browser, role: string): Promise<Page> {
  const storageState = path.resolve(__dirname, '../../../auth', `${role}.json`);
  if (!fs.existsSync(storageState)) throw new Error(`Нет сессии «${role}» (.qa/auth/${role}.json) — npm run qa-login:manual -- ${role}`);
  const { defaultBrowserType: _b, ...iphone } = devices['iPhone 13 Mini'];
  const ctx = await browser.newContext({ ...iphone, locale: 'he-IL', baseURL: baseUrl(), storageState });
  return ctx.newPage();
}

export function baseUrl(): string {
  const cfg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
  return process.env.QA_BASE_URL || cfg.baseUrl;
}

export async function closeAs(page: Page, role: string) {
  await saveSession(page, role);
  await page.context().close();
}

// Создать сторис через «סטורי חדש» (/story/new): картинка + подпись → «שיתוף»; ждёт POST /rest/v1/stories 201.
export async function createStory(page: Page, caption: string) {
  await page.goto('/story/new');
  await page.locator('input[type=file]').setInputFiles(path.resolve(__dirname, 'qa-auto-story.jpg'));
  await page.getByRole('textbox', { name: 'כיתוב (לא חובה)' }).fill(caption);
  const created = page.waitForResponse((r) => r.url().includes('/rest/v1/stories') && r.request().method() === 'POST');
  await page.getByRole('button', { name: 'שיתוף' }).click();
  expect((await created).status(), `создание сторис «${caption}»`).toBe(201);
}

// Удалить свою сторис через меню автора: ⋯ → «מחיקת הסטורי» → «מחיקה»; ждёт DELETE stories?id=eq.<id>.
export async function deleteOwnStory(page: Page, storyId: string) {
  await page.goto(`/story/${storyId}`);
  await menuButton(page).click();
  await page.getByRole('button', { name: /מחיקת הסטורי/ }).click();
  const del = page.waitForResponse((r) => r.request().method() === 'DELETE' && r.url().includes(`/rest/v1/stories?id=eq.${storyId}`));
  await page.getByRole('button', { name: 'מחיקה', exact: true }).click();
  expect((await del).ok(), `удаление сторис ${storyId}`).toBeTruthy();
}
